/** A dated setting's value (as the settings show it) recorded from `from` (yyyy-mm-dd). */
export type DatedValue = { from: string; value: string };

/** The floor a sheet starts with: in force before its first from-date. */
export const DEFAULT_FLOOR = '1.00';

/** The late percent a sheet starts with: in force before its first from-date. */
export const DEFAULT_LATE_PCT = '0.00';

/** The terms (days) a sheet starts with: in force before their first from-date. */
export const DEFAULT_TERMS = '14';

/** The value in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it, or undefined when none is. */
export function valueOn(values: DatedValue[] | undefined, date: string): string | undefined {
  const applying = (values ?? []).filter((v) => v.from <= date);
  return applying.reduce<DatedValue | undefined>((best, v) => (!best || v.from > best.from ? v : best), undefined)?.value;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import type { Late } from '../rates/ratesQuery';
import { claimsQuery } from '../claims/claimsQuery';
import type { Grade } from '../people/peopleQuery';
import { valueOn } from './dated';
import type { DatedValue } from './dated';


/** `clerkLimit` has two decimals ("1.50"), or is "" when there is no limit; `floor` has two decimals;
 *  `terms` is a whole number of days ("14"), and `gradeTerms` the terms in force for each grade (its own, else the sheet's); `latePct` is a percent with two decimals ("0.00");
 *  `policyDate` is yyyy-mm-dd, or "" when there is none (the sheet's today is the policy date); `periodNumberingFrom` is yyyy-mm-dd, or "" when numbering by period is off; `cap` has two decimals, or is "" when there is none.
 *  Those that carry a figure are as in force on the sheet's today when they were read; `dated` holds every value recorded for each of them, by key
 *  (clerk-limit, floor, terms, terms-<grade>, late-pct, cap, proof-threshold; a blank clerk limit, cap or proof threshold is none). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; gradeTerms: Record<Grade, string>; cap: string; dated: Record<string, DatedValue[]> };

/** What the request carries: a setting left out (or blank, for the floor, terms, a grade's terms and late percent) is left as it is; a blank policy date is none.
 *  `from` is the from-date (yyyy-mm-dd) a dated setting is recorded from, by key; left out, it is the sheet's today. */
export type SettingsChange = {
  clerkLimit?: string;
  floor?: string;
  terms?: string;
  latePct?: string;
  policyDate?: string;
  periodNumberingFrom?: string;
  gradeTerms?: Partial<Record<Grade, string>>;
  cap?: string;
  proofThreshold?: string;
  from?: Record<string, string>;
};

export type RoleName = 'clerk' | 'steward';

/** The role a sheet gives a user name; a name with no entry is a clerk. */
export type Role = { user: string; role: RoleName };

export const ROLES: RoleName[] = ['clerk', 'steward'];

/** Under the sheet's key, so re-loading the sheet re-reads its settings and roles. */
export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export const settingsQuery = (sheetId: string) => ({
  queryKey: settingsKey(sheetId),
  queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
});

/** A dated setting's value in force on the sheet's today, or `starting` when none is recorded on or before it. */
export function useCurrent(sheetId: string, key: string, starting = ''): string {
  const today = useSheetToday(sheetId);
  return valueOn(useQuery(settingsQuery(sheetId)).data?.dated?.[key], today) ?? starting;
}

/** The sheet's floors by from-date: what a claim's live due is at least, as in force on the claim's date. */
export function useFloor(sheetId: string): DatedValue[] {
  return useQuery(settingsQuery(sheetId)).data?.dated?.floor ?? [];
}

/** The sheet's cap in force on its today: what a person's due-total is at most ("" for none). */
export function useCap(sheetId: string): string {
  return useCurrent(sheetId, 'cap');
}

/** The sheet's late percents by from-date: what an overdue claim gains of its figure for every full 30 days it is overdue, as in force on the claim's date. */
export function useLatePct(sheetId: string): DatedValue[] {
  return useQuery(settingsQuery(sheetId)).data?.dated?.['late-pct'] ?? [];
}

/** The sheet's policy date (yyyy-mm-dd): the one set, or the sheet's today when there is none. */
export function usePolicyDate(sheetId: string): string {
  const today = useSheetToday(sheetId);
  return useQuery(settingsQuery(sheetId)).data?.policyDate || today;
}

/** What a claim's late charge and its rounding depend on, as the sheet has it now. */
export function useLate(sheetId: string): Late {
  return {
    today: useSheetToday(sheetId),
    pct: useLatePct(sheetId),
    policy: usePolicyDate(sheetId),
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
  };
}

export const rolesQuery = (sheetId: string) => ({
  queryKey: rolesKey(sheetId),
  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { ROLES, rolesKey, rolesQuery, settingsKey, settingsQuery } from './settingsQuery';
import { DEFAULT_FLOOR, DEFAULT_LATE_PCT, DEFAULT_TERMS, valueOn } from './dated';
import { useSheetToday } from '../sheet/useSheetToday';
import type { Role, RoleName, Settings as SheetSettings, SettingsChange } from './settingsQuery';
import { GRADES } from '../people/peopleQuery';
import type { Grade } from '../people/peopleQuery';

const AMOUNT = /^\d{1,9}(\.\d{1,2})?$/;
const DAYS = /^\d{1,4}$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

const isDate = (d: string) => DATE.test(d) && new Date(`${d}T00:00:00Z`).toISOString().slice(0, 10) === d;

/** The sheet's settings — the clerk limit a clerk may settle up to (blank: no limit) and the floor a
 *  claim's live due is at least, and the terms (days after its date a claim is due by) and the late percent (what an overdue claim gains per full 30 days) — and the form
 *  they are saved through. Each grade may have terms of its own (a grade without uses the sheet's terms); a claim's
 *  due-by is fixed from them when it is made. A blank floor, terms, grade's terms or late percent is left as it is, and so is a blank clerk
 *  limit saved with any of them. The policy date decides how a claim's figures round (blank: the sheet's
 *  today). A person's due-total is at most the cap (blank: none). A claim whose due is above the proof threshold in force on its date (blank: none) is settled or approved only once it has a proof. From the period numbering date on, an opened claim is numbered within its period (blank: off).
 *  A save with every field blank clears whichever of the clerk limit, the policy date, the period numbering
 *  date, the cap and the proof threshold was last worked in (the clerk limit unless it was one of the others).
 *  Each setting that carries a figure (all but the policy date and the period numbering date) is saved from its from-date
 *  (blank: the sheet's today), keeping the values recorded from other dates; what is shown in force is the value on the sheet's today. */
function Settings({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery(settingsQuery(sheetId));
  const [limit, setLimit] = useState('');
  const [floor, setFloor] = useState('');
  const [terms, setTerms] = useState('');
  const [gradeTerms, setGradeTerms] = useState<Partial<Record<Grade, string>>>({});
  const [latePct, setLatePct] = useState('');
  const [policyDate, setPolicyDate] = useState('');
  const [numberingFrom, setNumberingFrom] = useState('');
  const [cap, setCap] = useState('');
  const [threshold, setThreshold] = useState('');
  const [blank, setBlank] = useState<'clerkLimit' | 'policyDate' | 'periodNumberingFrom' | 'cap' | 'proofThreshold'>('clerkLimit');
  const [from, setFrom] = useState<Record<string, string>>({});
  const [error, setError] = useState('');
  const today = useSheetToday(sheetId);
  const dated = settings.data?.dated;
  const current = (key: string, starting = '') => (settings.data ? (valueOn(dated?.[key], today) ?? starting) : '');
  const currentTerms = current('terms', DEFAULT_TERMS);

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: SettingsChange) =>
      putJson<SheetSettings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
      setLimit('');
      setFloor('');
      setTerms('');
      setGradeTerms({});
      setLatePct('');
      setPolicyDate('');
      setNumberingFrom('');
      setCap('');
      setThreshold('');
      setFrom({});
    },
    onError: () => setError('The settings could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const l = limit.trim();
    if (l !== '' && !AMOUNT.test(l)) {
      setError('The clerk limit must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const f = floor.trim();
    if (f !== '' && !AMOUNT.test(f)) {
      setError('The floor must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const t = terms.trim();
    if (t !== '' && !DAYS.test(t)) {
      setError('The terms must be a whole number of days, 0 or more.');
      return;
    }
    const g: Partial<Record<Grade, string>> = {};
    for (const grade of GRADES) {
      const days = (gradeTerms[grade] ?? '').trim();
      if (days === '') continue;
      if (!DAYS.test(days)) {
        setError(`The terms of grade ${grade} must be a whole number of days, 0 or more.`);
        return;
      }
      g[grade] = days;
    }
    const p = latePct.trim();
    if (p !== '' && !AMOUNT.test(p)) {
      setError('The late percent must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const d = policyDate.trim();
    if (d !== '' && !isDate(d)) {
      setError('The policy date must be a date (yyyy-mm-dd).');
      return;
    }
    const n = numberingFrom.trim();
    if (n !== '' && !isDate(n)) {
      setError('The period numbering from-date must be a date (yyyy-mm-dd).');
      return;
    }
    const c = cap.trim();
    if (c !== '' && !AMOUNT.test(c)) {
      setError('The cap must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const pt = threshold.trim();
    if (pt !== '' && !AMOUNT.test(pt)) {
      setError('The proof threshold must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const froms: Record<string, string> = {};
    for (const [key, date] of Object.entries(from)) {
      const d = date.trim();
      if (d === '') continue;
      if (!isDate(d)) {
        setError('A from-date must be a date (yyyy-mm-dd).');
        return;
      }
      froms[key] = d;
    }
    const body: SettingsChange = {};
    const none = l === '' && f === '' && t === '' && Object.keys(g).length === 0 && p === '' && d === '' && n === '' && c === '' && pt === '';
    if (l !== '' || (none && blank === 'clerkLimit')) body.clerkLimit = l;
    if (d !== '' || (none && blank === 'policyDate')) body.policyDate = d;
    if (n !== '' || (none && blank === 'periodNumberingFrom')) body.periodNumberingFrom = n;
    if (c !== '' || (none && blank === 'cap')) body.cap = c;
    if (pt !== '' || (none && blank === 'proofThreshold')) body.proofThreshold = pt;
    if (f !== '') body.floor = f;
    if (t !== '') body.terms = t;
    if (Object.keys(g).length > 0) body.gradeTerms = g;
    if (p !== '') body.latePct = p;
    if (Object.keys(froms).length > 0) body.from = froms;
    once(() => save.mutateAsync(body));
  };

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form data-testid="settings-form" onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="no limit"
            value={limit}
            onFocus={() => setBlank('clerkLimit')}
            onChange={(e) => {
              setLimit(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-clerk-limit-from`}
            placeholder="sheet's today"
            value={from['clerk-limit'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['clerk-limit']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Floor{' '}
          <input
            data-testid="setting-floor"
            placeholder="unchanged"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-floor-from`}
            placeholder="sheet's today"
            value={from['floor'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['floor']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Terms (days){' '}
          <input
            data-testid="setting-terms"
            placeholder="unchanged"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-terms-from`}
            placeholder="sheet's today"
            value={from['terms'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['terms']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        {GRADES.map((grade) => (
          <span key={grade}>
            <label>
              Terms {grade} (days){' '}
              <input
                data-testid={`setting-terms-${grade}`}
                placeholder="unchanged"
                value={gradeTerms[grade] ?? ''}
                onChange={(e) => {
                  setGradeTerms({ ...gradeTerms, [grade]: e.target.value });
                  setError('');
                }}
              />
            </label>{' '}
            <label>
              from{' '}
              <input
                data-testid={`setting-terms-${grade}-from`}
                placeholder="sheet's today"
                value={from[`terms-${grade}`] ?? ''}
                onChange={(e) => {
                  setFrom({ ...from, [`terms-${grade}`]: e.target.value });
                  setError('');
                }}
              />
            </label>{' '}
          </span>
        ))}
        <label>
          Late percent{' '}
          <input
            data-testid="setting-late-pct"
            placeholder="unchanged"
            value={latePct}
            onChange={(e) => {
              setLatePct(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-late-pct-from`}
            placeholder="sheet's today"
            value={from['late-pct'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['late-pct']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Policy date{' '}
          <input
            data-testid="setting-policy-date"
            placeholder="sheet's today"
            value={policyDate}
            onFocus={() => setBlank('policyDate')}
            onChange={(e) => {
              setPolicyDate(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Period numbering from{' '}
          <input
            data-testid="setting-period-numbering-from"
            placeholder="off"
            value={numberingFrom}
            onFocus={() => setBlank('periodNumberingFrom')}
            onChange={(e) => {
              setNumberingFrom(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Cap{' '}
          <input
            data-testid="setting-cap"
            placeholder="none"
            value={cap}
            onFocus={() => setBlank('cap')}
            onChange={(e) => {
              setCap(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-cap-from`}
            placeholder="sheet's today"
            value={from['cap'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['cap']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Proof threshold{' '}
          <input
            data-testid="setting-proof-threshold"
            placeholder="none"
            value={threshold}
            onFocus={() => setBlank('proofThreshold')}
            onChange={(e) => {
              setThreshold(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          from{' '}
          <input
            data-testid={`setting-proof-threshold-from`}
            placeholder="sheet's today"
            value={from['proof-threshold'] ?? ''}
            onChange={(e) => {
              setFrom({ ...from, ['proof-threshold']: e.target.value });
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <p data-testid="settings-error">{error}</p>}
      </form>
      {settings.isError && <p data-testid="settings-load-error">Could not load the settings.</p>}
      <p>
        Clerk limit in force: <span data-testid="setting-clerk-limit-current">{current('clerk-limit')}</span>
      </p>
      <p>
        Floor in force: <span data-testid="setting-floor-current">{current('floor', DEFAULT_FLOOR)}</span>
      </p>
      <p>
