1:import { getJson } from '../../api/http';
2:import { counts } from '../claims/claimsQuery';
3:import type { Claim, ClaimStatus } from '../claims/claimsQuery';
4:import type { Person } from '../people/peopleQuery';
5:import { figure, sumDue } from '../rates/ratesQuery';
6:import type { Late, Rate } from '../rates/ratesQuery';
7:import { sheetKey } from '../sheet/sheetQuery';
8:import type { DatedValue } from '../settings/dated';
9:
10:/**
11: * A sheet's period: a name unique on the sheet, `from` and `to` (yyyy-mm-dd) inclusive. Periods never overlap.
12: * A closed period's due-total was fixed when it was closed (`closedTotal`; null while open), and so was each
13: * person's due-total for it (`personTotals`, by person id; empty while open, and a person added later has none).
14: */
15:export type Period = {
16:  name: string;
17:  from: string;
18:  to: string;
19:  closed: boolean;
20:  closedTotal: string | null;
21:  personTotals: Record<string, string>;
22:};
23:
24:/** Under the sheet's key, so re-loading the sheet re-reads its periods. */
25:export const periodsKey = (sheetId: string) => [...sheetKey(sheetId), 'periods'] as const;
26:
27:/** The sheet's periods, by from-date. */
28:export const periodsQuery = (sheetId: string) => ({
29:  queryKey: periodsKey(sheetId),
30:  queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
31:});
32:
33:/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
34:export function periodOf(periods: Period[], date: string): Period | undefined {
35:  return periods.find((p) => p.from <= date && date <= p.to);
36:}
37:
38:/**
39: * The claim's status at the end of the day `on` (yyyy-mm-dd), as its log records it: the last status logged on or
40: * before it, DRAFT (counting nowhere) when it was added after. A claim with no log has its status now.
41: */
42:export function statusOn(c: Claim, on: string): ClaimStatus {
43:  const log = c.log ?? [];
44:  if (log.length === 0) return c.status;
45:  let status: ClaimStatus = 'DRAFT';
46:  for (const line of log) {
47:    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
48:    if (m && m[2] <= on) status = m[1] as ClaimStatus;
49:  }
50:  return status;
51:}
52:
53:/**
54: * A person's due-total for a period: the figures (as shown now) of their claims dated in it that counted by the
55: * status they had at the end of its last day. While the period is
56: * closed it is the figure fixed when it was closed (0.00 for a person added since).
57: */
58:export function personPeriodDue(
59:  period: Period,
60:  person: Person,
61:  claims: Claim[],
62:  people: Person[],
63:  rates: Rate[],
64:  floor: DatedValue[],
65:  late: Late,
66:): string {
67:  if (period.closed) return period.personTotals[String(person.id)] ?? '0.00';
68:  return sumDue(
69:    claims
70:      .filter(
71:        (c) =>
72:          c.personId === person.id &&
73:          period.from <= c.date &&
74:          c.date <= period.to &&
75:          counts({ ...c, status: statusOn(c, period.to) }, people, late.today),
76:      )
77:      .map((c) => figure(c, rates, person, floor, late)),
78:  );
79:}
80:
81:/** A period's due-total: its people's due-totals for it added up. */
82:export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string {
83:  return sumDue(people.map((p) => personPeriodDue(period, p, claims, people, rates, floor, late)));
84:}

